pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        vm.assume(_feeRate <= 5000);
        bool ok;
        try c.initialize(address(0), address(0), 0, 0, 0, _feeRate, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(c.feeRate(), _feeRate);
        }
    }
}
